"use client"

import type { ReactNode } from "react"

import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandGroupLabel,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import { CommandDialog, CommandDialogContent } from "@/components/ui/command-dialog"
import { useDocumentWorkspace } from "@/components/ui/document-workspace-context"

type DocumentQuickOpenItem = {
  value: string
  label: string
  /** A folder or path, shown after the label. */
  description?: string
  keywords?: readonly string[]
  /** Items with the same group are listed under it. */
  group?: string
}

type DocumentQuickOpenLabels = { title: string; placeholder?: string; empty: ReactNode }

/**
 * Ctrl/Cmd+P in a `DocumentWorkspace`: a `CommandDialog` that searches `items` and calls `onOpen` with the chosen
 * value. Focus then goes back to the document, unless `onOpen` moved it.
 */
function DocumentQuickOpen({
  items,
  onOpen,
  labels: labelOverrides,
}: {
  items: readonly DocumentQuickOpenItem[]
  onOpen: (value: string) => void
  labels?: Partial<DocumentQuickOpenLabels>
}) {
  const workspace = useDocumentWorkspace()
  const labels = { title: workspace.labels.quickOpen, empty: "No matches", ...labelOverrides }
  const groups = new Map<string, DocumentQuickOpenItem[]>()
  for (const item of items) groups.set(item.group ?? "", [...(groups.get(item.group ?? "") ?? []), item])
  const row = (item: DocumentQuickOpenItem) => (
    <CommandItem key={item.value} value={item.value} label={item.label} keywords={item.keywords && [...item.keywords]}>
      <span className="truncate">{item.label}</span>
      {item.description && (
        <span className="ms-auto shrink-0 truncate text-caption text-muted-foreground">{item.description}</span>
      )}
    </CommandItem>
  )
  return (
    <CommandDialog
      controller={workspace.quickOpen}
      onOpenChangeComplete={(open) => open || workspace.refocusDocument()}
    >
      <CommandDialogContent title={labels.title} finalFocus={workspace.documentFocusTarget}>
        <Command
          onAction={(value) => {
            workspace.quickOpen.close()
            onOpen(value)
          }}
        >
          <CommandInput aria-label={labels.title} placeholder={labels.placeholder} />
          <CommandEmpty>{labels.empty}</CommandEmpty>
          <CommandList>
            {[...groups].map(([group, entries]) =>
              group ? (
                <CommandGroup key={group}>
                  <CommandGroupLabel>{group}</CommandGroupLabel>
                  {entries.map(row)}
                </CommandGroup>
              ) : (
                entries.map(row)
              ),
            )}
          </CommandList>
        </Command>
      </CommandDialogContent>
    </CommandDialog>
  )
}

export { DocumentQuickOpen }
export type { DocumentQuickOpenItem, DocumentQuickOpenLabels }

"use client"

import type { ReactNode, RefObject } from "react"
import { BookOpenIcon, PanelLeftIcon, PanelRightIcon, PencilIcon, SearchIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { CommandDialogTrigger } from "@/components/ui/command-dialog"
import type { DocumentSaveState, DocumentWorkspaceMode } from "@/components/ui/document-workspace-context"
import { SegmentedControl, SegmentedControlIndicator, SegmentedControlItem } from "@/components/ui/segmented-control"
import { StatusDot } from "@/components/ui/status-pill"
import type { DocumentWorkspaceState } from "@/components/ui/use-document-workspace-state"
import type { Tone } from "@/lib/tone"

const SAVE_TONES: Record<DocumentSaveState, Tone> = {
  saved: "success",
  saving: "info",
  unsaved: "warning",
  error: "destructive",
}

const toggleClassName = "shrink-0 text-muted-foreground aria-expanded:text-foreground"

type WorkspaceHeaderProps = {
  state: DocumentWorkspaceState
  tabs: ReactNode
  hasExplorer: boolean
  hasAside: boolean
  hasQuickOpen: boolean
  quickOpenShortcut: string | false
}

/** The explorer toggle, the tabs, the mode switch, quick open and the aside toggle. */
function WorkspaceHeader({
  state,
  tabs,
  hasExplorer,
  hasAside,
  hasQuickOpen,
  quickOpenShortcut,
}: WorkspaceHeaderProps) {
  const { labels, ids, context, explorer, aside } = state
  return (
    <div
      data-slot="document-workspace-header"
      className="flex min-w-0 flex-wrap items-center gap-inline border-b px-inset-item py-inline"
    >
      {hasExplorer && (
        <Button
          variant="ghost"
          size="icon"
          aria-label={labels.explorerToggle}
          aria-expanded={explorer.shown}
          aria-controls={ids.explorer}
          onClick={() => explorer.setOpen(!explorer.shown)}
          className={toggleClassName}
        >
          <PanelLeftIcon className="rtl:-scale-x-100" />
        </Button>
      )}
      {/* A narrow column gives the tabs a row of their own instead of squeezing them beside the controls. */}
      <div
        data-slot="document-workspace-tabs"
        className="min-w-0 flex-1 @max-xl/center:order-last @max-xl/center:basis-full"
      >
        {tabs}
      </div>
      <SegmentedControl<DocumentWorkspaceMode>
        aria-label={labels.mode}
        value={context.mode}
        onValueChange={(next) => next && context.setMode(next)}
        className="ms-auto shrink-0"
      >
        <SegmentedControlIndicator />
        <SegmentedControlItem value="edit" className="@max-xl:px-inline">
          <PencilIcon />
          <span className="@max-xl:sr-only">{labels.edit}</span>
        </SegmentedControlItem>
        <SegmentedControlItem value="read" className="@max-xl:px-inline">
          <BookOpenIcon />
          <span className="@max-xl:sr-only">{labels.read}</span>
        </SegmentedControlItem>
      </SegmentedControl>
      {hasQuickOpen && (
        <CommandDialogTrigger
          controller={context.quickOpen}
          shortcut={quickOpenShortcut || undefined}
          variant="ghost"
          size="icon"
          aria-label={labels.quickOpen}
          className={toggleClassName}
        >
          <SearchIcon />
        </CommandDialogTrigger>
      )}
      {hasAside && (
        <Button
          variant="ghost"
          size="icon"
          aria-label={labels.asideToggle}
          aria-expanded={aside.shown}
          aria-controls={ids.aside}
          onClick={() => aside.setOpen(!aside.shown)}
          className={toggleClassName}
        >
          <PanelRightIcon className="rtl:-scale-x-100" />
        </Button>
      )}
    </div>
  )
}

type WorkspaceCenterProps = Omit<WorkspaceHeaderProps, "tabs"> & {
  tabs?: ReactNode
  breadcrumb?: ReactNode
  toolbar?: ReactNode
  statusBar?: ReactNode
  saveState?: DocumentSaveState
  documentAs: "region" | "main"
  documentRef: RefObject<HTMLElement | null>
  children: ReactNode
}

/** The header, the breadcrumb bar, the document region and the status bar, in a column. */
function WorkspaceCenter({
  state,
  tabs,
  breadcrumb,
  toolbar,
  statusBar,
  saveState,
  documentAs,
  documentRef,
  children,
  ...header
}: WorkspaceCenterProps) {
  const { labels, context } = state
  const Document = documentAs === "main" ? "main" : "section"
  return (
    <div data-slot="document-workspace-center" className="@container/center flex size-full min-h-0 min-w-0 flex-col">
      <WorkspaceHeader state={state} tabs={tabs} {...header} />
      {(breadcrumb !== undefined || toolbar !== undefined) && (
        <div
          data-slot="document-workspace-bar"
          className="flex min-w-0 flex-wrap items-center gap-items border-b px-inset-item py-inline"
        >
          <div className="min-w-0 flex-1">{breadcrumb}</div>
          {toolbar !== undefined && <div className="flex shrink-0 items-center gap-inline">{toolbar}</div>}
        </div>
      )}
      <Document
        ref={documentRef}
        tabIndex={-1}
        aria-label={labels.document}
        data-slot="document-workspace-document"
        data-mode={context.mode}
        className="flex min-h-0 flex-1 flex-col overflow-auto outline-none data-[mode=read]:px-inset-surface data-[mode=read]:py-group"
      >
        {children}
      </Document>
      <div
        data-slot="document-workspace-status"
        className="flex min-w-0 items-center gap-items border-t px-inset-item py-inline text-caption text-muted-foreground"
      >
        <div className="flex min-w-0 flex-1 items-center gap-items">{statusBar}</div>
        <output data-state={saveState} className="inline-flex shrink-0 items-center gap-inline">
          {saveState && (
            <>
              <StatusDot tone={SAVE_TONES[saveState]} pulse={saveState === "saving"} label="" aria-hidden="true" />
              {labels[saveState]}
            </>
          )}
        </output>
      </div>
    </div>
  )
}

export { WorkspaceCenter }
export type { WorkspaceCenterProps }

"use client"

import type { CommandDialogController } from "@/components/ui/command-dialog"
import { createContext, use, type RefObject } from "react"

type DocumentWorkspaceMode = "edit" | "read"
type DocumentSaveState = "saved" | "saving" | "unsaved" | "error"

/** A heading of the open document, as `extractHeadings` (from `markdown-view`) returns it. */
type DocumentHeading = { level: number; text: string; line: number; textFrom: number }

/** What the workspace needs from an editor: `MarkdownEditorHandle` (from `markdown-editor`) has it. */
type DocumentEditor = {
  focus: () => void
  scrollToLine: (line: number) => void
  setSelection: (anchor: number, head?: number) => void
  getScrollLine: () => number
}

type DocumentWorkspaceLabels = {
  /** The explorer's navigation landmark and drawer title. */
  explorer: string
  /** The button that shows or hides the explorer. */
  explorerToggle: string
  /** The aside's complementary landmark and drawer title. */
  aside: string
  asideToggle: string
  /** The document region. */
  document: string
  /** The mode switch and its two choices. */
  mode: string
  edit: string
  read: string
  quickOpen: string
  resizeExplorer: string
  resizeAside: string
  saved: string
  saving: string
  unsaved: string
  error: string
}

const documentWorkspaceLabels: DocumentWorkspaceLabels = {
  explorer: "Files",
  explorerToggle: "Files",
  aside: "Details",
  asideToggle: "Details",
  document: "Document",
  mode: "Mode",
  edit: "Edit",
  read: "Read",
  quickOpen: "Quick open",
  resizeExplorer: "Resize files",
  resizeAside: "Resize details",
  saved: "Saved",
  saving: "Saving…",
  unsaved: "Unsaved changes",
  error: "Couldn't save",
}

type DocumentWorkspaceContextValue = {
  mode: DocumentWorkspaceMode
  /** Switches the mode, keeping the reading position by heading. */
  setMode: (mode: DocumentWorkspaceMode) => void
  narrow: boolean
  headings: readonly DocumentHeading[]
  editorRef: RefObject<DocumentEditor | null> | undefined
  /** The document region, which scrolls in read mode. */
  documentRef: RefObject<HTMLElement | null>
  /** Where focus goes back to: the editor's text in edit mode, the document region in read mode. */
  documentFocusTarget: () => HTMLElement | null
  /** Focuses the document once it is there: an editor that remounts for another note builds its view later. */
  focusDocument: () => void
  /** After a popup closed: focuses the document if focus was left nowhere in particular. */
  refocusDocument: () => void
  /** Read mode: scrolls the `index`th heading of the document to the top and moves focus to it. */
  revealHeading: (index: number) => void
  quickOpen: CommandDialogController
  setExplorerOpen: (open: boolean) => void
  setAsideOpen: (open: boolean) => void
  labels: DocumentWorkspaceLabels
}

const DocumentWorkspaceContext = createContext<DocumentWorkspaceContextValue | null>(null)

/** The enclosing `DocumentWorkspace`: its mode, headings, editor and focus helpers. */
function useDocumentWorkspace() {
  const context = use(DocumentWorkspaceContext)
  if (!context) throw new Error("useDocumentWorkspace needs a DocumentWorkspace around it.")
  return context
}

/** The rendered headings of a read view in `root`, leaving out any inside an embed. */
function readHeadings(root: HTMLElement | null) {
  if (!root) return []
  return [...root.querySelectorAll<HTMLElement>("h1, h2, h3, h4, h5, h6")].filter(
    (heading) => !heading.closest("[data-slot=markdown-embed], [data-slot=markdown-properties]"),
  )
}

function textBoxIn(root: HTMLElement | null) {
  return root?.querySelector<HTMLElement>("[contenteditable=true], [role=textbox], textarea") ?? null
}

export { DocumentWorkspaceContext, documentWorkspaceLabels, readHeadings, textBoxIn, useDocumentWorkspace }
export type {
  DocumentEditor,
  DocumentHeading,
  DocumentSaveState,
  DocumentWorkspaceContextValue,
  DocumentWorkspaceLabels,
  DocumentWorkspaceMode,
}

"use client"

import type { ComponentProps, MouseEvent, ReactNode } from "react"

import { Drawer, DrawerBackdrop, DrawerContent, DrawerTitle } from "@/components/ui/drawer"
import { Resizable, ResizableHandle, ResizablePanel } from "@/components/ui/resizable"
import type { DocumentWorkspaceState } from "@/components/ui/use-document-workspace-state"

type WorkspaceDrawerProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  side: "start" | "end"
  title: string
  finalFocus: ComponentProps<typeof DrawerContent>["finalFocus"]
  onClosed: () => void
  children: ReactNode
}

/** The explorer or the aside in the narrow layout: a 20rem drawer from its side, named by its landmark. */
function WorkspaceDrawer({ open, onOpenChange, side, title, finalFocus, onClosed, children }: WorkspaceDrawerProps) {
  return (
    <Drawer open={open} onOpenChange={onOpenChange} onOpenChangeComplete={(next) => next || onClosed()} side={side}>
      <DrawerBackdrop />
      <DrawerContent finalFocus={finalFocus} className="gap-0 p-0 data-[side=left]:max-w-80 data-[side=right]:max-w-80">
        <DrawerTitle className="sr-only">{title}</DrawerTitle>
        {children}
      </DrawerContent>
    </Drawer>
  )
}

type PanelsProps = { state: DocumentWorkspaceState; explorer?: ReactNode; aside?: ReactNode }

/** The wide layout: the explorer, the center and the aside as resizable columns that collapse to nothing. */
function WorkspaceColumns({ state, explorer, aside, children }: PanelsProps & { children: ReactNode }) {
  const { ids, labels, stored, controller } = state
  return (
    <Resizable controller={controller} onLayoutCommit={state.remember} className="min-h-0 flex-1">
      {explorer !== undefined && (
        <>
          <ResizablePanel
            id={ids.explorer}
            collapsible
            collapsedSize={0}
            minSize="180px"
            maxSize="45%"
            defaultSize={state.explorer.open ? (stored.explorerSize ?? "256px") : 0}
            render={<nav aria-label={labels.explorer} />}
            data-slot="document-workspace-explorer"
            className="bg-muted/(--glass-opacity)"
          >
            {explorer}
          </ResizablePanel>
          <ResizableHandle aria-label={labels.resizeExplorer} />
        </>
      )}
      <ResizablePanel id={ids.center} minSize="320px" className="overflow-hidden">
        {children}
      </ResizablePanel>
      {aside !== undefined && (
        <>
          <ResizableHandle aria-label={labels.resizeAside} />
          <ResizablePanel
            id={ids.aside}
            collapsible
            collapsedSize={0}
            minSize="220px"
            maxSize="45%"
            defaultSize={state.aside.open ? (stored.asideSize ?? "288px") : 0}
            render={<aside aria-label={labels.aside} />}
            data-slot="document-workspace-aside"
          >
            {aside}
          </ResizablePanel>
        </>
      )}
    </Resizable>
  )
}

/** The narrow layout: the explorer and the aside as drawers from their sides. */
function WorkspaceDrawers({ state, explorer, aside }: PanelsProps) {
  const { ids, labels, context } = state
  const onClosed = () => context.refocusDocument()

  // A file chosen in the drawer is navigation: the drawer closes and focus goes to the document.
  const closeOnLink = (event: MouseEvent<HTMLElement>) => {
    if (event.target instanceof Element && event.target.closest("a[href]")) state.explorer.setOpen(false)
  }

  return (
    <>
      {explorer !== undefined && (
        <WorkspaceDrawer
          open={state.explorer.drawerOpen}
          onOpenChange={state.explorer.setOpen}
          side="start"
          title={labels.explorer}
          finalFocus={context.documentFocusTarget}
          onClosed={onClosed}
        >
          {/* oxlint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-noninteractive-element-interactions -- hears the clicks of the links inside, which Enter fires too */}
          <nav
            id={ids.explorer}
            aria-label={labels.explorer}
            data-slot="document-workspace-explorer"
            onClick={closeOnLink}
            className="min-h-0 flex-1 overflow-auto"
          >
            {explorer}
          </nav>
        </WorkspaceDrawer>
      )}
      {aside !== undefined && (
        <WorkspaceDrawer
          open={state.aside.drawerOpen}
          onOpenChange={state.aside.setOpen}
          side="end"
          title={labels.aside}
          finalFocus={context.documentFocusTarget}
          onClosed={onClosed}
        >
          <aside
            id={ids.aside}
            aria-label={labels.aside}
            data-slot="document-workspace-aside"
            className="min-h-0 flex-1 overflow-auto"
          >
            {aside}
          </aside>
        </WorkspaceDrawer>
      )}
    </>
  )
}

export { WorkspaceColumns, WorkspaceDrawer, WorkspaceDrawers }

"use client"

import { Button } from "@/components/ui/button"
import { useDocumentWorkspace, type DocumentHeading } from "@/components/ui/document-workspace-context"
import { cn } from "@/lib/utils"

type DocumentOutlineProps = {
  /** The headings to list; the workspace's `headings` by default. */
  headings?: readonly DocumentHeading[]
  /** The navigation landmark's name. */
  label?: string
  /** Deeper headings are left out. */
  maxLevel?: number
  className?: string
}

/**
 * The document's headings as buttons. In edit mode one puts the caret at its heading's text, scrolled to the top,
 * and focuses the editor; in read mode it scrolls to the heading and moves focus to it.
 */
function DocumentOutline({ headings: own, label = "Outline", maxLevel = 6, className }: DocumentOutlineProps) {
  const workspace = useDocumentWorkspace()
  const headings = own ?? workspace.headings
  const shallowest = Math.min(...headings.map((heading) => heading.level))

  const go = (index: number) => {
    const heading = headings[index]
    if (!heading) return
    const editor = workspace.editorRef?.current
    if (workspace.mode === "edit" && editor) {
      editor.setSelection(heading.textFrom)
      editor.scrollToLine(heading.line)
      editor.focus()
      return
    }
    workspace.revealHeading(index)
  }

  return (
    <nav aria-label={label} data-slot="document-outline" className={cn("flex min-w-0 flex-col", className)}>
      <ol className="flex flex-col">
        {headings.map(
          (heading, index) =>
            heading.level <= maxLevel && (
              <li key={`${String(heading.line)}:${heading.text}`}>
                <Button
                  variant="ghost"
                  size="sm"
                  data-level={heading.level}
                  onClick={() => go(index)}
                  className="w-full min-w-0 justify-start gap-0 px-inset-item pointer-coarse:h-(--control-height-touch) font-normal text-muted-foreground hover:text-foreground data-[level='1']:font-medium data-[level='1']:text-foreground"
                >
                  <span
                    aria-hidden="true"
                    data-depth={Math.min(heading.level - shallowest, 5)}
                    className="shrink-0 data-[depth='1']:w-3 data-[depth='2']:w-6 data-[depth='3']:w-9 data-[depth='4']:w-12 data-[depth='5']:w-15"
                  />
                  <span className="truncate">{heading.text}</span>
                </Button>
              </li>
            ),
        )}
      </ol>
    </nav>
  )
}

export { DocumentOutline }
export type { DocumentOutlineProps }

"use client"

import { useRef, type ReactNode, type RefObject } from "react"

import { WorkspaceCenter } from "@/components/ui/document-workspace-center"
import {
  DocumentWorkspaceContext,
  documentWorkspaceLabels,
  useDocumentWorkspace,
  type DocumentEditor,
  type DocumentHeading,
  type DocumentSaveState,
  type DocumentWorkspaceLabels,
  type DocumentWorkspaceMode,
} from "@/components/ui/document-workspace-context"
import { WorkspaceColumns, WorkspaceDrawers } from "@/components/ui/document-workspace-panels"
import { DocumentOutline, type DocumentOutlineProps } from "@/components/ui/document-workspace-parts"
import {
  DocumentQuickOpen,
  type DocumentQuickOpenItem,
  type DocumentQuickOpenLabels,
} from "@/components/ui/document-quick-open"
import { useDocumentWorkspaceState } from "@/components/ui/use-document-workspace-state"
import { cn } from "@/lib/utils"

type DocumentWorkspaceProps = {
  /** The open document: a `MarkdownEditor` in edit mode, a `MarkdownView` in read mode. */
  document: ReactNode
  /** A file tree or list, inside a navigation landmark: a resizable column when wide, a drawer when narrow. */
  explorer?: ReactNode
  /** Open documents, like a `TabsList`, in the header. */
  tabs?: ReactNode
  breadcrumb?: ReactNode
  /** Document actions, like a menu or a `MarkdownEditorToolbar` of your own, beside the breadcrumb. */
  toolbar?: ReactNode
  /** Word count, cursor position: before the save status. */
  statusBar?: ReactNode
  /** Backlinks, properties, a `DocumentOutline`, in a complementary landmark. */
  aside?: ReactNode
  /** A message read out at once when it appears, like a conflict `Alert` with your actions. */
  alert?: ReactNode
  /** A `DocumentQuickOpen`; with it, the header gets a Quick open button and `quickOpenShortcut`. */
  quickOpen?: ReactNode
  mode?: DocumentWorkspaceMode
  defaultMode?: DocumentWorkspaceMode
  onModeChange?: (mode: DocumentWorkspaceMode) => void
  explorerOpen?: boolean
  defaultExplorerOpen?: boolean
  onExplorerOpenChange?: (open: boolean) => void
  asideOpen?: boolean
  defaultAsideOpen?: boolean
  onAsideOpenChange?: (open: boolean) => void
  /** At this container width (px) or below, the explorer and the aside become drawers. 760 by default. */
  narrow?: number
  saveState?: DocumentSaveState
  labels?: Partial<DocumentWorkspaceLabels>
  /** Remembers whether the explorer and the aside are open, and their widths, in localStorage under this key. */
  storageKey?: string
  /** The editor's handle, for the outline, focus return and the reading position across modes. */
  editorRef?: RefObject<DocumentEditor | null>
  /** The document's headings, from `extractHeadings`: the outline lists them and a mode switch keeps to them. */
  headings?: readonly DocumentHeading[]
  /** `false` turns it off. */
  quickOpenShortcut?: string | false
  /** `"main"` when the workspace is the page's main content; inside an app shell's `<main>`, a named region. */
  documentAs?: "region" | "main"
  className?: string
}

function DocumentWorkspace(props: DocumentWorkspaceProps) {
  const { document: content, explorer, aside, alert, quickOpen, className } = props
  const rootRef = useRef<HTMLDivElement>(null)
  const documentRef = useRef<HTMLElement>(null)
  const state = useDocumentWorkspaceState(props, rootRef, documentRef)
  const center = (
    <WorkspaceCenter
      state={state}
      documentRef={documentRef}
      tabs={props.tabs}
      breadcrumb={props.breadcrumb}
      toolbar={props.toolbar}
      statusBar={props.statusBar}
      saveState={props.saveState}
      documentAs={props.documentAs ?? "region"}
      hasExplorer={explorer !== undefined}
      hasAside={aside !== undefined}
      hasQuickOpen={quickOpen !== undefined}
      quickOpenShortcut={props.quickOpenShortcut ?? "mod+p"}
    >
      {content}
    </WorkspaceCenter>
  )

  return (
    <DocumentWorkspaceContext value={state.context}>
      <div
        ref={rootRef}
        data-slot="document-workspace"
        data-layout={state.narrow ? "narrow" : "wide"}
        data-mode={state.context.mode}
        className={cn(
          "@container flex h-(--document-workspace-height,100%) min-h-0 w-full min-w-0 flex-col overflow-hidden bg-background text-body text-foreground",
          className,
        )}
      >
        <div
          role="alert"
          aria-atomic="true"
          data-slot="document-workspace-alert"
          className="not-empty:border-b not-empty:px-inset-item not-empty:py-inline"
        >
          {alert}
        </div>
        {state.narrow ? (
          <>
            {center}
            <WorkspaceDrawers state={state} explorer={explorer} aside={aside} />
          </>
        ) : (
          <WorkspaceColumns state={state} explorer={explorer} aside={aside}>
            {center}
          </WorkspaceColumns>
        )}
        {quickOpen}
      </div>
    </DocumentWorkspaceContext>
  )
}

export { DocumentOutline, DocumentQuickOpen, DocumentWorkspace, documentWorkspaceLabels, useDocumentWorkspace }
export type {
  DocumentEditor,
  DocumentHeading,
  DocumentOutlineProps,
  DocumentQuickOpenItem,
  DocumentQuickOpenLabels,
  DocumentSaveState,
  DocumentWorkspaceLabels,
  DocumentWorkspaceMode,
  DocumentWorkspaceProps,
}

"use client"

import { useId, useState, type RefObject } from "react"

import { createCommandDialogController } from "@/components/ui/command-dialog"
import type { DocumentWorkspaceProps } from "@/components/ui/document-workspace"
import {
  documentWorkspaceLabels,
  textBoxIn,
  type DocumentHeading,
  type DocumentWorkspaceContextValue,
  type DocumentWorkspaceMode,
} from "@/components/ui/document-workspace-context"
import { createResizableController } from "@/components/ui/resizable"
import {
  focusWhenReady,
  openSizes,
  readPanels,
  revealHeading,
  useContainerNarrow,
  useControllable,
  useModeScroll,
  usePanel,
  watchLostFocus,
  writePanels,
} from "@/components/ui/use-document-workspace"

const NO_HEADINGS: readonly DocumentHeading[] = []

type WorkspaceIds = { explorer: string; center: string; aside: string }

/**
 * Everything `DocumentWorkspace` decides: the layout from its width, the mode, whether each side panel is open
 * (a column when wide, a drawer when narrow), what storage remembers, and the context its parts read.
 */
function useDocumentWorkspaceState(
  props: DocumentWorkspaceProps,
  rootRef: RefObject<HTMLDivElement | null>,
  documentRef: RefObject<HTMLElement | null>,
) {
  const { storageKey, editorRef, explorer, aside } = props
  const headings = props.headings ?? NO_HEADINGS
  const labels = { ...documentWorkspaceLabels, ...props.labels }
  const narrow = useContainerNarrow(rootRef, props.narrow ?? 760)
  const id = useId()
  const ids: WorkspaceIds = { explorer: `${id}-explorer`, center: `${id}-document`, aside: `${id}-aside` }
  const [stored] = useState(() => readPanels(storageKey))
  const [controller] = useState(() => createResizableController())
  const [quickOpen] = useState(() => createCommandDialogController())

  const [mode, setModeState] = useControllable(props.mode, () => props.defaultMode ?? "edit", props.onModeChange)
  const [explorerOpen, setExplorerState] = useControllable(
    props.explorerOpen,
    () => stored.explorer ?? props.defaultExplorerOpen ?? true,
    props.onExplorerOpenChange,
  )
  const [asideOpen, setAsideState] = useControllable(
    props.asideOpen,
    () => stored.aside ?? props.defaultAsideOpen ?? true,
    props.onAsideOpenChange,
  )
  // Only the wide layout's choice is remembered: the drawers always start closed.
  const setExplorerOpen = (open: boolean) => {
    if (!narrow) writePanels(storageKey, { explorer: open })
    setExplorerState(open)
  }
  const setAsideOpen = (open: boolean) => {
    if (!narrow) writePanels(storageKey, { aside: open })
    setAsideState(open)
  }
  const panel = { narrow, controller }
  const explorerPanel = usePanel({ ...panel, open: explorerOpen, setOpen: setExplorerOpen, panelId: ids.explorer })
  const asidePanel = usePanel({ ...panel, open: asideOpen, setOpen: setAsideOpen, panelId: ids.aside })

  const captureScroll = useModeScroll({ mode, headings, editorRef, documentRef })
  const setMode = (next: DocumentWorkspaceMode) => {
    if (next === mode) return
    captureScroll()
    setModeState(next)
  }

  const documentFocusTarget = () =>
    mode === "edit" ? (textBoxIn(documentRef.current) ?? documentRef.current) : documentRef.current
  const context: DocumentWorkspaceContextValue = {
    mode,
    setMode,
    narrow,
    headings,
    editorRef,
    documentRef,
    documentFocusTarget,
    revealHeading: (index) => revealHeading(documentRef.current, index),
    focusDocument: () => focusWhenReady(() => (mode === "edit" ? textBoxIn(documentRef.current) : documentRef.current)),
    refocusDocument: () => watchLostFocus(documentRef.current, () => context.focusDocument()),
    quickOpen,
    setExplorerOpen,
    setAsideOpen,
    labels,
  }

  // A collapse by the handle (Enter, a double-click, a drag past half the minimum) closes the panel too.
  const remember = (layout: number[]) => {
    const panels = { explorerSize: explorer === undefined ? null : ids.explorer, center: ids.center }
    writePanels(
      storageKey,
      openSizes(controller, layout, { ...panels, asideSize: aside === undefined ? null : ids.aside }),
    )
    if (explorer !== undefined && controller.isCollapsed(ids.explorer) === explorerOpen) setExplorerOpen(!explorerOpen)
    if (aside !== undefined && controller.isCollapsed(ids.aside) === asideOpen) setAsideOpen(!asideOpen)
  }

  return {
    ids,
    labels,
    narrow,
    stored,
    controller,
    context,
    remember,
    explorer: {
      open: explorerOpen,
      shown: narrow ? explorerPanel.drawerOpen : explorerOpen,
      drawerOpen: explorerPanel.drawerOpen,
      setOpen: setExplorerOpen,
    },
    aside: {
      open: asideOpen,
      shown: narrow ? asidePanel.drawerOpen : asideOpen,
      drawerOpen: asidePanel.drawerOpen,
      setOpen: setAsideOpen,
    },
  }
}

type DocumentWorkspaceState = ReturnType<typeof useDocumentWorkspaceState>

export { useDocumentWorkspaceState }
export type { DocumentWorkspaceState, WorkspaceIds }

"use client"

import { useEffect, useEffectEvent, useLayoutEffect, useRef, useState, type RefObject } from "react"

import type { ResizableController } from "@/components/ui/resizable"
import {
  readHeadings,
  type DocumentEditor,
  type DocumentHeading,
  type DocumentWorkspaceMode,
} from "@/components/ui/document-workspace-context"

type StoredPanels = { explorer?: boolean; aside?: boolean; explorerSize?: number; asideSize?: number }

// Storage can throw (blocked site data, a sandboxed frame) or be missing (a server); the panels then just don't
// remember.
function readPanels(key: string | undefined): StoredPanels {
  if (!key) return {}
  try {
    const raw = localStorage.getItem(key)
    const parsed: unknown = raw ? JSON.parse(raw) : null
    return parsed && typeof parsed === "object" ? (parsed as StoredPanels) : {}
  } catch {
    return {}
  }
}

function writePanels(key: string | undefined, patch: StoredPanels) {
  if (!key) return
  try {
    localStorage.setItem(key, JSON.stringify({ ...readPanels(key), ...patch }))
  } catch {
    // Not remembered, still applied for this page.
  }
}

/** The sizes of the panels that are open in a committed layout, by key; `null` marks a panel that isn't there. */
function openSizes(controller: ResizableController, layout: number[], panels: Record<string, string | null>) {
  const present = Object.entries(panels).filter((entry): entry is [string, string] => entry[1] !== null)
  const sizes = present.flatMap(([key, panel], index) =>
    key.endsWith("Size") && !controller.isCollapsed(panel) ? [[key, layout[index]]] : [],
  )
  return Object.fromEntries(sizes) as StoredPanels
}

/** Whether `ref`'s element is at most `width` px wide; false until it has been measured. */
function useContainerNarrow(ref: RefObject<HTMLElement | null>, width: number) {
  const [narrow, setNarrow] = useState(false)
  useLayoutEffect(() => {
    const element = ref.current
    if (!element) return
    const measure = () => setNarrow(element.getBoundingClientRect().width <= width)
    measure()
    if (typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    return () => observer.disconnect()
  }, [ref, width])
  return narrow
}

/** A value the parent may control: `value` wins when set, and `onChange` hears every change. */
function useControllable<T>(value: T | undefined, initial: () => T, onChange?: (next: T) => void) {
  const [own, setOwn] = useState(initial)
  const current = value ?? own
  const set = (next: T) => {
    if (next === current) return
    if (value === undefined) setOwn(next)
    onChange?.(next)
  }
  return [current, set] as const
}

type PanelOptions = {
  narrow: boolean
  open: boolean
  setOpen: (open: boolean) => void
  controller: ResizableController
  panelId: string
}

/**
 * One side panel, a resizable column when wide and a drawer when narrow. Entering the narrow layout closes it, so a
 * drawer never pops open on its own, and leaving it brings back what the column was.
 */
function usePanel({ narrow, open, setOpen, controller, panelId }: PanelOptions) {
  // Derived while rendering, so the drawer stays shut in the render where the layout turns narrow: it may show
  // only once it has opened in this layout.
  const [track, setTrack] = useState({ narrow, open, allowed: false })
  let allowed = track.allowed
  if (track.narrow !== narrow || track.open !== open) {
    allowed = narrow !== track.narrow ? false : open && !track.open ? true : track.allowed
    setTrack({ narrow, open, allowed })
  }

  const wide = useRef<boolean | null>(null)
  const onLayout = useEffectEvent((isNarrow: boolean) => {
    if (isNarrow) {
      if (wide.current === null) wide.current = open
      if (open) setOpen(false)
    } else if (wide.current !== null) {
      const restore = wide.current
      wide.current = null
      if (restore !== open) setOpen(restore)
    }
  })
  useEffect(() => onLayout(narrow), [narrow])

  useEffect(() => {
    if (narrow) return
    if (open && controller.isCollapsed(panelId)) controller.expand(panelId)
    else if (!open && !controller.isCollapsed(panelId)) controller.collapse(panelId)
  }, [narrow, open, controller, panelId])

  return { drawerOpen: narrow && open && allowed }
}

type ModeScrollOptions = {
  mode: DocumentWorkspaceMode
  headings: readonly DocumentHeading[]
  editorRef: RefObject<DocumentEditor | null> | undefined
  documentRef: RefObject<HTMLElement | null>
}

function scrollToElement(container: HTMLElement, element: HTMLElement) {
  container.scrollTop += element.getBoundingClientRect().top - container.getBoundingClientRect().top
}

/** Focuses what `find` returns as soon as it exists, for up to a second. */
function focusWhenReady(find: () => HTMLElement | null) {
  let frames = 0
  const step = () => {
    const target = find()
    if (target) target.focus({ preventScroll: true })
    else if (frames++ < 60) requestAnimationFrame(step)
  }
  step()
}

/**
 * For half a second after a popup closes, focus left on nothing (the body, or the region an editor was replaced
 * in) goes back to the document. A note opened from the popup remounts the editor that focus returned to.
 */
function watchLostFocus(region: HTMLElement | null, refocus: () => void) {
  const until = performance.now() + 500
  const step = () => {
    const active = document.activeElement
    if (!active || active === document.body || active === region) {
      refocus()
      return
    }
    if (performance.now() < until) requestAnimationFrame(step)
  }
  step()
}

/** Runs `step` on each frame until it returns true, for up to a second; the result cancels it. */
function eachFrame(step: () => boolean) {
  let frames = 0
  let frame = 0
  const run = () => {
    if (step() || ++frames >= 60) return
    frame = requestAnimationFrame(run)
  }
  frame = requestAnimationFrame(run)
  return () => cancelAnimationFrame(frame)
}

function revealHeading(container: HTMLElement | null, index: number) {
  const target = readHeadings(container)[index]
  if (!container || !target) return
  scrollToElement(container, target)
  if (!target.hasAttribute("tabindex")) target.tabIndex = -1
  target.focus({ preventScroll: true })
}

/**
 * Keeps the reading position across a mode switch, by heading: `capture` notes the heading at the top before the
 * switch, and once the other mode has rendered, it is scrolled to the top there.
 */
function useModeScroll({ mode, headings, editorRef, documentRef }: ModeScrollOptions) {
  const pending = useRef<number | null>(null)

  const capture = () => {
    if (mode === "edit") {
      const line = editorRef?.current?.getScrollLine() ?? 1
      pending.current = headings.findLastIndex((heading) => heading.line <= line)
      return
    }
    const container = documentRef.current
    if (!container) return
    const top = container.getBoundingClientRect().top + 4
    pending.current = readHeadings(container).findLastIndex((heading) => heading.getBoundingClientRect().top <= top)
  }

  const restore = useEffectEvent((index: number, to: DocumentWorkspaceMode) => {
    // The other mode's view mounts its content a frame or more later (an editor builds its view in an effect).
    return eachFrame(() => {
      if (to === "read") {
        const container = documentRef.current
        const target = readHeadings(container)[index]
        if (!container || (!target && index >= 0)) return false
        if (target) scrollToElement(container, target)
        else container.scrollTop = 0
        return true
      }
      const editor = editorRef?.current
      if (!editor) return false
      editor.scrollToLine(index >= 0 ? (headings[index]?.line ?? 1) : 1)
      return true
    })
  })

  useEffect(() => {
    const index = pending.current
    pending.current = null
    if (index === null) return
    return restore(index, mode)
  }, [mode])

  return capture
}

export {
  focusWhenReady,
  openSizes,
  readPanels,
  revealHeading,
  useContainerNarrow,
  useControllable,
  useModeScroll,
  usePanel,
  watchLostFocus,
  writePanels,
}
export type { StoredPanels }
